import { loadFromGitHub } from 'gowm';

// Load db module from wasm-modules-repository
const db = await loadFromGitHub('benoitpetit/wasm-modules-repository', {
  path: 'db-wasm',
  name: 'db-wasm',
  branch: 'master'
});

// Configure module
db.call('setSilentMode', true);

// Create a new database
const createResult = db.call('createDatabase', 'mydb');
if (createResult.success) {
  console.log('Database created:', createResult.message);
}

// Insert data - supports all types
db.call('insertData', 'mydb', 'username', 'john_doe');
db.call('insertData', 'mydb', 'age', 25);
db.call('insertData', 'mydb', 'settings', {theme: 'dark', lang: 'fr'});
db.call('insertData', 'mydb', 'active', true);

// Get data
const user = db.call('getData', 'mydb', 'username');
if (user.success) {
  console.log('Username:', user.data.value); // 'john_doe'
}

// List all keys
const keys = db.call('listKeys', 'mydb');
console.log('Keys:', keys.data.keys); // ['username', 'age', 'settings', 'active']
console.log('Count:', keys.data.count); // 4

// Export database to JSON
const exported = db.call('exportDatabase', 'mydb');
if (exported.success) {
  const jsonData = exported.data.data;
  console.log('Exported data:', jsonData);

  // Save to file or send to server
  const blob = new Blob([jsonData], {type: 'application/json'});
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'mydb-export.json';
  link.click();
}

// Create new database and import
db.call('createDatabase', 'backup');

// Import with merge (keeps existing data)
const importResult = db.call('importDatabase', 'backup', jsonData, false);
console.log('Imported:', importResult.data.imported, 'entries');

// Or import with replace (clears existing data)
db.call('importDatabase', 'backup', jsonData, true);

// Get database statistics
const stats = db.call('getStats', 'backup');
console.log('Database stats:', {
  name: stats.data.name,
  entries: stats.data.entries,
  size: stats.data.storageSizeKB + ' KB'
});

// Create database
db.call('createDatabase', 'users');

