import { loadFromGitHub } from 'gowm';

class DatabaseManager {
  constructor() {
    this.db = null;
    this.ready = false;
    this.currentDatabase = null;
    this.loadModule();
  }

  async loadModule() {
    try {
      this.db = await loadFromGitHub('benoitpetit/wasm-modules-repository', {
        path: 'db-wasm',
              name: 'db-wasm'
      });

      // Configure for production use
      this.db.call('setSilentMode', true);

      // Get available functions
      const functions = this.db.call('getAvailableFunctions');
      console.log('Available db functions:', functions);

      this.ready = true;
    } catch (error) {
      console.error('Failed to load db module:', error);
    }
  }

  // Initialize or open database
  useDatabase(name) {
    if (!this.ready) throw new Error('Database module not ready');

    const result = this.db.call('createDatabase', name);
    if (result.success) {
      this.currentDatabase = name;
    }
    return result;
  }

  // CRUD operations on current database
  set(key, value) {
    if (!this.currentDatabase) throw new Error('No database selected');
    return this.db.call('insertData', this.currentDatabase, key, value);
  }

  get(key) {
    if (!this.currentDatabase) throw new Error('No database selected');
    const result = this.db.call('getData', this.currentDatabase, key);
    return result.success ? result.data.value : null;
  }

  delete(key) {
    if (!this.currentDatabase) throw new Error('No database selected');
    return this.db.call('deleteData', this.currentDatabase, key);
  }

  keys() {
    if (!this.currentDatabase) throw new Error('No database selected');
    const result = this.db.call('listKeys', this.currentDatabase);
    return result.success ? result.data.keys : [];
  }

  all() {
    if (!this.currentDatabase) throw new Error('No database selected');
    const result = this.db.call('getAllData', this.currentDatabase);
    return result.success ? result.data.data : {};
  }

  clear() {
    if (!this.currentDatabase) throw new Error('No database selected');
    return this.db.call('clearDatabase', this.currentDatabase);
  }

  stats() {
    if (!this.currentDatabase) throw new Error('No database selected');
    const result = this.db.call('getStats', this.currentDatabase);
    return result.success ? result.data : null;
  }

  // Export/Import utilities
  export() {
    if (!this.currentDatabase) throw new Error('No database selected');
    const result = this.db.call('exportDatabase', this.currentDatabase);
    return result.success ? result.data.data : null;
  }

  import(jsonData, replace = false) {
    if (!this.currentDatabase) throw new Error('No database selected');
    return this.db.call('importDatabase', this.currentDatabase, jsonData, replace);
  }
}

// Usage example
const dbManager = new DatabaseManager();

// Wait for module to load
setTimeout(() => {
  if (dbManager.ready) {
    // Use database
    dbManager.useDatabase('myapp');

    // Set data
    dbManager.set('config', {theme: 'dark', language: 'fr'});
    dbManager.set('user', {name: 'Alice', id: 123});

    // Get data
    console.log('Config:', dbManager.get('config'));
    console.log('User:', dbManager.get('user'));

    // List all keys
    console.log('All keys:', dbManager.keys());

    // Get all data
    console.log('All data:', dbManager.all());

    // Database stats
    console.log('Stats:', dbManager.stats());

    // Export data
    const exported = dbManager.export();
    console.log('Exported:', exported);
  }
}, 1000);
